-- Fictional US consumer-finance lead-generation business. All data is generated by scripts/seed.py.
DROP SCHEMA IF EXISTS leadflow CASCADE;
CREATE SCHEMA leadflow;
SET search_path = leadflow;

CREATE TABLE affiliates (
    affiliate_id serial PRIMARY KEY,
    name         text NOT NULL UNIQUE,
    tier         text NOT NULL CHECK (tier IN ('gold', 'silver', 'bronze')),
    status       text NOT NULL CHECK (status IN ('active', 'paused', 'restricted')),
    joined_on    date NOT NULL
);

CREATE TABLE campaigns (
    campaign_id  serial PRIMARY KEY,
    affiliate_id int NOT NULL REFERENCES affiliates,
    name         text NOT NULL,
    channel      text NOT NULL CHECK (channel IN ('search', 'social', 'email', 'display')),
    product      text NOT NULL CHECK (product IN ('personal_loan', 'auto_loan', 'debt_relief', 'credit_repair')),
    payout       numeric(8, 2) NOT NULL  -- paid to the affiliate per sold lead
);

CREATE TABLE buyers (
    buyer_id   serial PRIMARY KEY,
    name       text NOT NULL UNIQUE,
    buyer_type text NOT NULL CHECK (buyer_type IN ('lender', 'network')),
    status     text NOT NULL CHECK (status IN ('active', 'paused'))
);

CREATE TABLE leads (
    lead_id      serial PRIMARY KEY,
    campaign_id  int NOT NULL REFERENCES campaigns,
    received_at  timestamp NOT NULL,  -- US Eastern
    product      text NOT NULL,
    state        char(2) NOT NULL,
    loan_amount  int NOT NULL,
    credit_band  text NOT NULL CHECK (credit_band IN ('excellent', 'good', 'fair', 'poor')),
    is_duplicate boolean NOT NULL
);

-- Each lead is offered to buyers in turn (position 1, 2, ...) until one accepts.
CREATE TABLE pings (
    ping_id     serial PRIMARY KEY,
    lead_id     int NOT NULL REFERENCES leads,
    buyer_id    int NOT NULL REFERENCES buyers,
    position    int NOT NULL,
    bid_price   numeric(8, 2) NOT NULL,
    accepted    boolean NOT NULL,
    response_ms int NOT NULL
);

CREATE TABLE sales (
    sale_id          serial PRIMARY KEY,
    lead_id          int NOT NULL UNIQUE REFERENCES leads,
    buyer_id         int NOT NULL REFERENCES buyers,
    sold_at          timestamp NOT NULL,
    price            numeric(8, 2) NOT NULL,
    affiliate_payout numeric(8, 2) NOT NULL
);

CREATE TABLE returns (
    return_id   serial PRIMARY KEY,
    sale_id     int NOT NULL UNIQUE REFERENCES sales,
    returned_at timestamp NOT NULL,
    reason      text NOT NULL CHECK (reason IN ('invalid_contact', 'duplicate', 'fraud', 'not_interested'))
);

-- Sensitive: the read-only role gets no access, and the SQL guard rejects it too.
CREATE TABLE staff_accounts (
    account_id    serial PRIMARY KEY,
    email         text NOT NULL UNIQUE,
    password_hash text NOT NULL,
    role          text NOT NULL
);

CREATE INDEX ON campaigns (affiliate_id);
CREATE INDEX ON leads (campaign_id);
CREATE INDEX ON leads (received_at);
CREATE INDEX ON pings (lead_id);
CREATE INDEX ON pings (buyer_id);
CREATE INDEX ON sales (buyer_id);
CREATE INDEX ON sales (sold_at);
